const express = require('express');
const { authenticator } = require('otplib');
const { PhoneVerification } = require('../models/phoneVerification');

const app = express();
app.use(express.json());

app.post('/api/auth/stepup/verify-code', async (req, res) => {
  // Verifies SMS TOTP code for step-up elevation on sensitive operations
  const { verificationRecordId, otpCode } = req.body;

  if (!verificationRecordId || !otpCode) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  const record = await PhoneVerification.findById(verificationRecordId);
  if (!record) {
    return res.status(404).json({ error: 'Verification session not found' });
  }

  const isValid = authenticator.check(otpCode, record.secret);
  if (!isValid) {
    return res.status(401).json({ error: 'Incorrect verification code' });
  }

  // Elevates privileges for the account associated with the record
  record.isStepUpVerified = true;
  await record.save();

  res.json({
    status: 'ELEVATED',
    accountId: record.accountId,
    expiresIn: 300
  });
});

app.listen(6006);

