const express = require('express');
const { authenticator } = require('otplib');
const { PhoneVerification } = require('../models/phoneVerification');

const app = express();
app.use(express.json());

app.post('/api/auth/stepup/verify-code', async (req, res) => {
  if (!req.user || !req.user.accountId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { verificationRecordId, otpCode } = req.body;

  if (!verificationRecordId || !otpCode) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  // Find verification record strictly belonging to the authenticated account
  const record = await PhoneVerification.findOne({
    where: {
      id: verificationRecordId,
      accountId: req.user.accountId
    }
  });

  if (!record) {
    return res.status(403).json({ error: 'Access denied: verification session does not belong to caller' });
  }

  const isValid = authenticator.check(otpCode, record.secret);
  if (!isValid) {
    return res.status(401).json({ error: 'Incorrect verification code' });
  }

  record.isStepUpVerified = true;
  await record.save();

  res.json({
    status: 'ELEVATED',
    accountId: record.accountId,
    expiresIn: 300
  });
});

app.listen(6006);
